import { Match as M, Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";

import * as CheckboxGroup from "../../ui/base-ui-checkbox-group";

// MODEL

export const ProtocolValue = S.Union([
  S.Literal("http"),
  S.Literal("https"),
  S.Literal("ssh"),
]);
export type ProtocolValue = typeof ProtocolValue.Type;

export const Model = S.Struct({
  selectedProtocols: S.Array(ProtocolValue),
});

export type Model = typeof Model.Type;

// MESSAGE

export const ToggledProtocol = m("ToggledProtocol", { value: ProtocolValue });

export const Message = S.Union([ToggledProtocol]);
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{ selectedProtocols: ["http"] }, []];

// UPDATE

export const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      ToggledProtocol: ({ value }) => [
        evo(model, {
          selectedProtocols: (selectedProtocols) =>
            CheckboxGroup.toggleValue(selectedProtocols, value),
        }),
        [],
      ],
    })
  );

// VIEW

export const view = Submodel.defineView<Model, Message>((model): Html => {
  const h = html<Message>();

  return h.form(
    [h.Class("w-full max-w-sm")],
    [
      h.fieldset(
        [
          h.Attribute("role", "group"),
          h.Attribute("aria-labelledby", "allowed-network-protocols-label"),
          h.Class(CheckboxGroup.checkboxGroupRootClassName),
        ],
        [
          h.legend(
            [
              h.Id("allowed-network-protocols-label"),
              h.Class(CheckboxGroup.checkboxGroupCaptionClassName),
            ],
            ["Allowed network protocols"]
          ),
          h.div(
            [h.Class(CheckboxGroup.checkboxGroupItemsClassName)],
            [
              CheckboxGroup.itemView<Message>({
                value: "http",
                selectedValues: model.selectedProtocols,
                label: "HTTP",
                onValueChange: ToggledProtocol({ value: "http" }),
              }),
              CheckboxGroup.itemView<Message>({
                value: "https",
                selectedValues: model.selectedProtocols,
                label: "HTTPS",
                onValueChange: ToggledProtocol({ value: "https" }),
              }),
              CheckboxGroup.itemView<Message>({
                value: "ssh",
                selectedValues: model.selectedProtocols,
                label: "SSH",
                onValueChange: ToggledProtocol({ value: "ssh" }),
              }),
            ]
          ),
        ]
      ),
    ]
  );
});

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as BaseUiCheckboxGroupFormExample from "./main";

describe("Base UI Checkbox Group Form example", () => {
  test("matches the Base UI form integration content", () => {
    Scene.scene(
      {
        update: BaseUiCheckboxGroupFormExample.update,
        view: BaseUiCheckboxGroupFormExample.view,
      },
      Scene.with(BaseUiCheckboxGroupFormExample.init()[0]),
      Scene.expect(
        Scene.role("group", { name: "Allowed network protocols" })
      ).toExist(),
      Scene.expect(Scene.role("checkbox", { name: "HTTP" })).toHaveAttr(
        "aria-checked",
        "true"
      ),
      Scene.expect(Scene.role("checkbox", { name: "SSH" })).toHaveAttr(
        "aria-checked",
        "false"
      ),
      Scene.click(Scene.text("SSH")),
      Scene.expect(Scene.role("checkbox", { name: "SSH" })).toHaveAttr(
        "aria-checked",
        "true"
      )
    );
  });
});
